import type { NextConfig } from 'next';

/** Backend API (server-side only). The browser never talks to it directly. */
const apiUrl = (process.env.API_URL ?? 'http://localhost:4000').replace(/\/+$/, '');
const isDev = process.env.NODE_ENV === 'development';

/**
 * CSP without nonces: Cache Components (partial prerendering) cannot use per-request
 * nonces, so inline scripts generated by Next are allowed with 'unsafe-inline'.
 * Everything else (API calls, images, fonts) is same-origin thanks to the proxy.
 */
const csp = [
  "default-src 'self'",
  `script-src 'self' 'unsafe-inline'${isDev ? " 'unsafe-eval'" : ''}`,
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' blob: data:",
  "font-src 'self'",
  `connect-src 'self'${isDev ? ' ws:' : ''}`,
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
].join('; ');

const securityHeaders = [
  { key: 'Content-Security-Policy', value: csp },
  { key: 'X-Content-Type-Options', value: 'nosniff' },
  { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
  { key: 'X-Frame-Options', value: 'DENY' },
  { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
];

const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
  poweredByHeader: false,
  // Keep `next dev` from generating extra files in the project.
  agentRules: false,
  turbopack: {
    rules: {
      '*.css': {
        loaders: ['@tailwindcss/turbopack'],
        as: '*.css',
      },
    },
  },
  images: {
    // Product images are proxied to the API under the same origin (see rewrites), so the
    // optimizer never has to reach a private IP and only this path can be optimized.
    localPatterns: [{ pathname: '/uploads/**', search: '' }],
    qualities: [75],
    formats: ['image/webp'],
  },
  async rewrites() {
    return [
      { source: '/api/v1/:path*', destination: `${apiUrl}/api/v1/:path*` },
      { source: '/uploads/:path*', destination: `${apiUrl}/uploads/:path*` },
    ];
  },
  async headers() {
    return [{ source: '/:path*', headers: securityHeaders }];
  },
};

export default nextConfig;
